                if (
                    ip_obj.is_private
                    or ip_obj.is_loopback
                    or ip_obj.is_link_local
                    or ip_obj.is_multicast
                    or ip_obj.is_reserved
                ):
                    raise urllib.error.URLError(
                        "Redirect to internal/private IP not allowed"
                    )
        except socket.gaierror:
            raise urllib.error.URLError("Cannot resolve redirect hostname")

        return super().redirect_request(req, fp, code, msg, headers, newurl)


def fetch_page_metadata(page_url: str) -> dict:
    """
    Fetches HTML content from the given URL and extracts the title and description.

    Parameters:
        page_url (str): The URL of the page to scrape.

    Returns:
        dict: A dictionary containing 'title' and 'description' keys.
              In case of an error, the dictionary will contain an 'error' key
              with a descriptive message.
    """
    # --- 1. Validate the URL scheme and hostname ---
    parsed = urllib.parse.urlparse(page_url)
    if parsed.scheme not in ("http", "https"):
        return {"error": "Invalid URL scheme. Only http and https are allowed."}
    hostname = parsed.hostname
    if not hostname:
        return {"error": "Invalid URL, no hostname."}

    # --- 2. SSRF protection: reject private/internal IP addresses ---
    try:
        for info in socket.getaddrinfo(hostname, None):
            ip = info[4][0]
            ip_obj = ipaddress.ip_address(ip)
            if (
                ip_obj.is_private
                or ip_obj.is_loopback
                or ip_obj.is_link_local
                or ip_obj.is_multicast
                or ip_obj.is_reserved
            ):
                return {
                    "error": "Access to internal/private IP addresses is not allowed."
                }
    except socket.gaierror:
        return {"error": "Cannot resolve hostname."}

    # --- 3. Set up SSL context using certifi ---
    context = ssl.create_default_context(cafile=certifi.where())

    # --- 4. Build a custom opener with redirect safety ---
    opener = urllib.request.build_opener(
        SafeRedirectHandler(),
        urllib.request.HTTPSHandler(context=context),
    )

    # --- 5. Make the HTTP request ---
    req = urllib.request.Request(
        page_url,
        headers={"User-Agent": "Mozilla/5.0 (compatible; SocialMediaBot/1.0)"},
    )

    try:
        with opener.open(req, timeout=10) as response:
            # Limit the amount of data read to avoid memory exhaustion
            html_bytes = response.read(1_048_576)  # 1 MB limit

            # Attempt to detect the encoding from the Content-Type header
            content_type = response.headers.get_content_type()
            encoding = "utf-8"
            if content_type and "charset=" in content_type:
                encoding = content_type.split("charset=")[-1].strip()

            try:
                html = html_bytes.decode(encoding)
            except (UnicodeDecodeError, LookupError):
                html = html_bytes.decode("utf-8", errors="ignore")

    except urllib.error.HTTPError as e:
        return {"error": f"HTTP error {e.code}: {e.reason}"}
    except urllib.error.URLError as e:
        return {"error": f"URL error: {e.reason}"}
    except Exception as e:
        return {"error": f"Unexpected error: {str(e)}"}

    # --- 6. Parse the HTML and extract metadata ---
    parser = MetadataParser()
    try:
        parser.feed(html)
    except Exception as e:
        return {"title": "", "description": "", "error": f"Parsing error: {str(e)}"}

    return {
        "title": parser.title,
        "description": parser.description,
    }
